do $$ begin
  if not exists (select 1 from pg_roles where rolname='anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname='service_role') then create role service_role nologin bypassrls; end if;
end $$;
create schema auth;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
create function auth.role() returns text language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claim.role', true),''),'service_role') $$;
create table organizations(id uuid primary key default gen_random_uuid(), name text, slug text unique);
create table profiles(id uuid primary key references auth.users, email text, role text not null default 'user', organization_id uuid references organizations, full_name text);
create table organization_members(id uuid primary key default gen_random_uuid(), organization_id uuid, user_id uuid, role text);
create table organization_settings(organization_id uuid primary key, require_mfa bool default false, require_sso bool default false);
create table api_keys(id serial primary key, key text unique, user_id uuid, key_hash text, organization_id uuid, is_active bool default true, scopes jsonb default '[]');
create table webhooks(id serial primary key, user_id uuid, url text);
create table notification_settings(id serial primary key, user_id uuid);
create table audit_logs(id uuid primary key default gen_random_uuid(), user_id uuid, organization_id uuid);
create function public.is_org_member(p_org_id uuid) returns bool language sql security definer as $$ select exists(select 1 from organization_members where organization_id=p_org_id and user_id=auth.uid()) $$;
alter table organizations enable row level security; alter table profiles enable row level security; alter table organization_members enable row level security;
alter table organization_settings enable row level security; alter table api_keys enable row level security; alter table webhooks enable row level security;
alter table notification_settings enable row level security; alter table audit_logs enable row level security;
create policy profiles_select_own on profiles for select using (auth.uid()=id);
create policy profiles_update_own on profiles for update using (auth.uid()=id) with check (auth.uid()=id);
create policy api_keys_own on api_keys for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy webhooks_own on webhooks for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy notification_settings_own on notification_settings for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy organization_settings_member_read on organization_settings for select to authenticated using (is_org_member(organization_id));
create policy organizations_member_read on organizations for select to authenticated using (is_org_member(id));
create policy audit_logs_select_own on audit_logs for select using (auth.uid()=user_id);
-- mirror live grants: Supabase default privileges gave anon/authenticated everything on public
grant usage on schema public, auth to anon, authenticated, service_role;
grant all on all tables in schema public to anon, authenticated, service_role;
grant all on all sequences in schema public to anon, authenticated, service_role;
grant execute on all functions in schema public to public, anon, authenticated, service_role;
grant execute on function auth.uid(), auth.role() to anon, authenticated, service_role;
